// get the itemID that represents a template, or use the default itemID if template is not used
let ARM= materialize(SAPWSAlertRuleMetaData);
let Item4TemplateID= toscalar(ARM | where AnalyticsTemplateId == "{TemplateID}" | project ItemId);
let Item4RuleID= toscalar(ARM | where AnalyticsTemplateId == "{RuleID}" | project ItemId);
// use the itemID from the template, rule ID or DefaultItemID if all fails
print ItemID= coalesce(Item4TemplateID,Item4RuleID, "{DefaultItemID}" )
| extend Item4RuleID, DefaultItemID= "{DefaultItemID}", TemplateID= "{TemplateID}"

// get the itemID that represents a template, or use the alert rule ID for setting new values
let ARM= materialize(SAPWSAlertRuleMetaData);
let Item4TemplateID= toscalar(ARM | where AnalyticsTemplateId == "{TemplateID}" | project ItemId);
// use the itemID from the template, or rule ID when setting controls values
